const ME = 'teamlaunchbench@gmail.com';
const TESTRUN = 'teamlaunchbench+lb-testrun@gmail.com';
const out = [];
for (const [index, item] of $input.all().entries()) {
  const j = item.json;
  const isSeed = Boolean(j.seed_id);
  let fromAddr, fromName, subject, body, received, replyTo;
  if (isSeed) {
    fromAddr = String(j.from_address || '').toLowerCase();
    fromName = j.from_name || '';
    subject = j.subject || '';
    body = j.body || '';
    const s = String(j.seed_now || '');
    received = s.includes('T') ? s : s.replace(' ', 'T') + ':00+05:30';
    replyTo = TESTRUN;
  } else {
    const f = (j.from && j.from.value && j.from.value[0]) || {};
    fromAddr = String(f.address || '').toLowerCase();
    fromName = f.name || '';
    subject = j.subject || '';
    body = j.text || '';
    received = j.date || new Date().toISOString();
    const rt = j.replyTo && j.replyTo.value && j.replyTo.value[0];
    replyTo = rt && rt.address ? rt.address : fromAddr;
  }
  if (!isSeed && fromAddr === ME) continue;

  const tag = subject.match(/\[\s*as\s+([^\]]+)\]/i);
  const asAlias = tag ? tag[1].trim().toLowerCase() : '';
  subject = subject.replace(/\[\s*as\s+[^\]]+\]/gi, '').replace(/\s{2,}/g, ' ').trim();

  const kept = [];
  for (const line of String(body).replace(/\r/g, '').split('\n')) {
    const t = line.trim();
    if (/^On .+wrote:$/.test(t) || /^-{2,}\s*Original Message/i.test(t)) break;
    if (t.startsWith('>')) continue;
    kept.push(line);
  }
  const clean = kept.join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 6000);

  const names = [];
  const binary = {};
  for (const [key, b] of Object.entries(item.binary || {})) {
    names.push(b.fileName || key);
    if (!binary.pdf && (b.mimeType === 'application/pdf' || /\.pdf$/i.test(b.fileName || ''))) binary.pdf = b;
  }

  out.push({
    json: {
      source: isSeed ? 'seed' : 'live',
      seed_id: isSeed ? String(j.seed_id) : '',
      message_id: isSeed ? '' : j.id,
      thread_id: isSeed ? '' : j.threadId,
      from_address: fromAddr,
      from_name: fromName,
      reply_to: replyTo,
      subject,
      as_alias: asAlias,
      body: clean,
      now: DateTime.fromISO(received).setZone('Asia/Kolkata').toISO({ suppressMilliseconds: true }),
      attachments: names.join(', '),
      has_pdf: Boolean(binary.pdf),
      // Test runner only: classify and log, but don't run the handlers (regression runs).
      triage_only: isSeed && Boolean(j.triage_only)
    },
    binary,
    pairedItem: { item: index }
  });
}
return out;

// Guardrail: identity clues must appear in the email itself. Anything the model
// inferred (e.g. a company name guessed from the sender's domain) is removed,
// so a lookalike domain can never be matched to a real member.
const CENTRES = { KOR: ['koramangala'], IND: ['indiranagar'], HSR: ['hsr'], WHF: ['whitefield'], HEB: ['hebbal', 'manyata'] };
const email = $('Attach knowledge base').item.json;
const text = ((email.subject || '') + '\n' + (email.body || '')).toLowerCase();
const out = JSON.parse(JSON.stringify($json.output));
const clues = out.identity_clues || {};
const removed = [];

const stated = (field, v) => {
  if (field === 'centre') return text.includes(v.toLowerCase()) || (CENTRES[v] || []).some(n => text.includes(n));
  if (field === 'cabin') return text.includes(v.replace(/cabin|\s/gi, '').toLowerCase());
  if (field === 'company') return (v.match(/[A-Za-z]{4,}/g) || []).some(w => text.includes(w.toLowerCase()));
  return text.includes(v.toLowerCase());
};

for (const [field, val] of Object.entries(clues)) {
  if (Array.isArray(val)) {
    const keep = val.filter(v => !v || stated(field, String(v)));
    for (const v of val) if (v && !keep.includes(v)) removed.push(field + ': ' + v);
    clues[field] = keep;
  } else if (val && !stated(field, String(val))) {
    removed.push(field + ': ' + val);
    clues[field] = '';
  }
}
out.identity_clues = clues;

// Guardrail: an email written in an Indian script (Devanagari, Kannada, Tamil, ...)
// is language "other". Flash-Lite sometimes calls Hindi in Devanagari "hinglish",
// which is reserved for Hindi written in Latin letters.
const indic = (text.match(/[ऀ-෿]/g) || []).length;
if (indic >= 10 && out.language !== 'other') {
  removed.push(`language: ${out.language} (the email is in an Indian script, so "other")`);
  out.language = 'other';
}
out.guard_removed = removed;
return { json: { output: out } };

// One item holding the KB text plus the personas, members and testers tabs, so
// each email is merged with them once (Attach knowledge base) instead of re-reading.
// The KB is downloaded from Drive for every batch of emails.
return [{ json: {
  kb: $('Pass on the knowledge base').first().json.kb,
  personas: $('Read personas').all().map(i => i.json),
  members: $('Read members').all().map(i => i.json),
  testers: $('Read testers').all().map(i => i.json).filter(t => t.tester_email),
} }];

// Who is this email from? Demo-mode rules, docs/workflow-design.md section 2.
// 1. An [as <alias>] subject tag (test runner, presenter) picks a persona.
// 2. Else a member named in the email: exactly one match on member ID, GSTIN,
//    company name, or cabin plus centre (cabin names repeat across centres).
// 3. Else, for member-only classes (facility issue, billing, change request):
//    a. the sender's domain is a member's domain (seed emails), else
//    b. the tester's member_alias in the testers tab, else
//    c. the member persona assigned to the fewest testers, remembered in the
//       testers tab (the "Remember the assignment" step), so a tester is the
//       same company in every email.
// 4. Else the sender is a prospect.
const MEMBER_CLASSES = ['facility_issue', 'customer_billing', 'change_request'];
const ref = $('Attach knowledge base').item.json;
const personas = ref.personas || [];
const members = ref.members || [];
const testers = ref.testers || [];
const clues = ($json.output && $json.output.identity_clues) || {};
const norm = s => String(s || '').trim().toLowerCase();
const GENERIC = ['private', 'limited', 'technologies', 'solutions', 'studio', 'labs', 'india', 'services', 'payments'];
const words = s => (norm(s).match(/[a-z0-9]{4,}/g) || []).filter(w => !GENERIC.includes(w));

let member = null;
let assign = null;
let identity = { type: 'prospect', member_id: '', vendor_id: '', company: clues.company || '', source: 'none' };
const asMember = (m, source) => { member = m; identity = { type: 'member', member_id: m.member_id, vendor_id: '', company: m.company, source }; };

const persona = ref.as_alias ? personas.find(p => norm(p.alias) === norm(ref.as_alias) || norm(p.ref_id) === norm(ref.as_alias)) : null;
if (persona) {
  if (persona.type === 'member') member = members.find(m => m.member_id === persona.ref_id) || null;
  identity = { type: persona.type, member_id: member ? member.member_id : '', vendor_id: persona.type === 'member' ? '' : persona.ref_id,
    company: member ? member.company : persona.as_name, source: 'tag ' + persona.alias };
} else {
  const tests = [
    ['member ID', m => clues.member_id && norm(m.member_id) === norm(clues.member_id)],
    ['GSTIN', m => clues.gstin && norm(m.gstin) === norm(clues.gstin)],
    ['company', m => { const w = words(clues.company); return w.length > 0 && w.every(x => norm(m.company).includes(x)); }],
    ['cabin', m => clues.cabin && clues.centre && m.centre === clues.centre && norm(m.space).replace(/\s/g, '').includes(norm(clues.cabin).replace(/cabin|\s/g, ''))],
  ];
  for (const [label, test] of tests) {
    const hits = members.filter(test);
    if (hits.length === 1) { asMember(hits[0], 'email ' + label); break; }
  }
}

const intents = ($json.output && $json.output.intents) || [];
if (!member && identity.type === 'prospect' && intents.some(i => MEMBER_CLASSES.includes(i.class))) {
  const sender = norm(ref.from_address);
  const domain = sender.split('@')[1] || '';
  const byDomain = members.filter(m => domain && norm(m.email_domain) === domain);
  const tester = testers.find(t => norm(t.tester_email) === sender);
  const pinned = tester && tester.member_alias
    ? personas.find(p => p.type === 'member' && (norm(p.alias) === norm(tester.member_alias) || norm(p.ref_id) === norm(tester.member_alias))) : null;
  const pinnedMember = pinned && members.find(m => m.member_id === pinned.ref_id);
  if (byDomain.length === 1) asMember(byDomain[0], 'sender domain');
  else if (pinnedMember) asMember(pinnedMember, 'tester ' + pinned.alias);
  else if (ref.source === 'live' && sender) {
    const used = {};
    for (const t of testers) if (t.member_alias) used[norm(t.member_alias)] = (used[norm(t.member_alias)] || 0) + 1;
    const pool = personas.filter(p => p.type === 'member' && members.some(m => m.member_id === p.ref_id && m.status === 'Active'))
      .sort((a, b) => (used[norm(a.alias)] || 0) - (used[norm(b.alias)] || 0));
    if (pool.length) {
      asMember(members.find(m => m.member_id === pool[0].ref_id), 'assigned ' + pool[0].alias);
      assign = { tester_email: sender, tester_name: (tester && tester.tester_name) || ref.from_name || '',
        member_alias: pool[0].alias, assigned_on: String(ref.now).slice(0, 10) };
    }
  }
}
return { json: { output: $json.output, identity, member, assign } };

// What WF-1 needs: the email, the classifier output and the resolved identity.
const e = $('Attach knowledge base').item.json;
const r = $('Resolve identity').item.json;
return { json: {
  source: e.source, seed_id: e.seed_id, message_id: e.message_id, thread_id: e.thread_id,
  from_address: e.from_address, from_name: e.from_name, reply_to: e.reply_to,
  subject: e.subject, body: e.body, now: e.now,
  classifier: r.output, identity: r.identity, member: r.member,
} };

