// What WF-4 needs: the email, its PDF, the classifier output, the resolved
// identity, and who an [as ...] tag says the sender is (for the domain check).
const e = $('Attach knowledge base').item.json;
const r = $('Resolve identity').item.json;
const alias = String(e.as_alias || '').toLowerCase();
const persona = alias ? (e.personas || []).find(p => String(p.alias).toLowerCase() === alias || String(p.ref_id).toLowerCase() === alias) : null;
// Find this email's PDF explicitly (item pairing through the KB merge is ambiguous).
const src = $('Normalise email').all().find(i => (e.seed_id && i.json.seed_id === e.seed_id) || (e.message_id && i.json.message_id === e.message_id));
const bin = (src && src.binary) || {};
return {
  json: {
    source: e.source, seed_id: e.seed_id, message_id: e.message_id, thread_id: e.thread_id,
    from_address: e.from_address, from_name: e.from_name, reply_to: e.reply_to,
    subject: e.subject, body: e.body, now: e.now, attachments: e.attachments,
    has_pdf: Boolean(bin.pdf), tagged: Boolean(persona), effective_from: persona ? persona.as_email : e.from_address,
    classifier: r.output, identity: r.identity,
  },
  binary: bin.pdf ? { data: bin.pdf } : {},
};

// What WF-5 needs: the email, the classifier output, the resolved member, and
// the knowledge base text (questions are answered from it). A question inside
// a lead is left to WF-1, whose quote answers it.
const e = $('Attach knowledge base').item.json;
const r = $('Resolve identity').item.json;
return { json: {
  source: e.source, seed_id: e.seed_id, message_id: e.message_id, thread_id: e.thread_id,
  from_address: e.from_address, from_name: e.from_name, reply_to: e.reply_to,
  subject: e.subject, body: e.body, now: e.now, kb: e.kb,
  classifier: r.output, identity: r.identity, member: r.member,
} };

// What WF-2 needs: the email, the classifier output (issue fields, language,
// churn risk) and the resolved member.
const e = $('Attach knowledge base').item.json;
const r = $('Resolve identity').item.json;
return { json: {
  source: e.source, seed_id: e.seed_id, message_id: e.message_id, thread_id: e.thread_id,
  from_address: e.from_address, from_name: e.from_name, reply_to: e.reply_to,
  subject: e.subject, body: e.body, now: e.now,
  classifier: r.output, identity: r.identity, member: r.member,
} };

// What WF-3 needs: the email (with attachment names, so a promised GST
// certificate can be checked), the classifier output and the resolved member.
// A billing remark inside a membership change is left to WF-5, whose approval
// card already lists the member's open invoices.
const e = $('Attach knowledge base').item.json;
const r = $('Resolve identity').item.json;
return { json: {
  source: e.source, seed_id: e.seed_id, message_id: e.message_id, thread_id: e.thread_id,
  from_address: e.from_address, from_name: e.from_name, reply_to: e.reply_to,
  subject: e.subject, body: e.body, now: e.now, attachments: e.attachments || '',
  classifier: r.output, identity: r.identity, member: r.member,
} };

// Bulk mail (newsletters, marketing, mailing lists, auto-replies, no-reply
// notifications) is filed without an AI call, so spam sent to a harvested
// address can't use up the Gemini quota. A person writing from their own
// mailbox never sends these headers, so testers and real customers get through.
const j = $json;
const h = j.headers || {};
const val = k => String(h[k] || '').replace(/^[^:]*:\s*/, '').trim().toLowerCase();
const from = String((j.from && j.from.value && j.from.value[0] && j.from.value[0].address) || '').toLowerCase();
const binary = $input.item.binary || {};
const hasPdf = Object.values(binary).some(b => b.mimeType === 'application/pdf' || /\.pdf$/i.test(b.fileName || ''));

const reasons = [];
if (h['list-unsubscribe']) reasons.push('List-Unsubscribe header');
if (h['list-id']) reasons.push('List-Id header');
if (/^(bulk|list|junk)$/.test(val('precedence'))) reasons.push('Precedence: ' + val('precedence'));
if (val('auto-submitted') && val('auto-submitted') !== 'no') reasons.push('Auto-Submitted: ' + val('auto-submitted'));
const cat = (j.labelIds || []).find(l => ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS'].includes(l));
if (cat) reasons.push('Gmail category ' + cat.replace('CATEGORY_', '').toLowerCase());
if (/^(no-?reply|do-?not-?reply|mailer-daemon|postmaster)@/.test(from)) reasons.push('no-reply sender');

// Never skipped: anything with a PDF (a supplier's billing system may add list
// headers to an invoice).
const keep = hasPdf;
return { json: { ...j, bulk_reason: keep ? '' : reasons.join('; ') }, binary };

// One triage_log row for a bulk email, in the same columns as a classified one.
const j = $json;
const f = (j.from && j.from.value && j.from.value[0]) || {};
return { json: {
  logged_at: $now.setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm:ss'), source: 'live', message_id: j.id, thread_id: j.threadId,
  seed_id: '', now: DateTime.fromISO(j.date || new Date().toISOString()).setZone('Asia/Kolkata').toISO({ suppressMilliseconds: true }),
  from: f.name ? `${f.name} <${f.address}>` : (f.address || ''), reply_to: f.address || '', subject: j.subject || '', as_alias: '', attachments: '',
  desk: 'none', classes: 'noise/bulk', summary: 'Bulk or automated mail, filed without classification.',
  sentiment: '', churn_risk: false, language: '', confidence: 1, identity_clues: '', fraud_signals: '',
  reasoning: `Not sent to the AI: ${j.bulk_reason}.`, classifier_json: '',
} };

// Always read the knowledge base fresh from Drive. (An hourly cache in the
// workflow's static data was tried and removed: static data also holds the Gmail
// trigger's bookmark, and runs that saved the cache could write back an old
// bookmark, making the trigger re-read old unread mail.)
return [{ json: { fresh: false, kb: '' } }];

// Pass the downloaded knowledge base on. Nothing is stored between runs (see
// "Knowledge base needed"); if the download failed, stop so WF-E raises an alert.
const j = $input.first().json;
const kb = String(j.kb || '');
if (kb) return [{ json: { kb, source: 'drive' } }];
throw new Error('Could not download the knowledge base from Drive: ' + JSON.stringify(j.error || j).slice(0, 300));
